const $=s=>document.querySelector(s), main=$('#main'), dialog=$('#editor');
let db, exhibitions=[], draft, urls=[];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const url=o=>{let u=URL.createObjectURL(o.blob);urls.push(u);return u};
const cleanup=()=>{urls.forEach(URL.revokeObjectURL);urls=[]};
const sample={id:'sample',title:'My first apartment',intro:'A small beginning. A place that slowly became mine.',objects:[{title:'The first set of keys',note:'I picked these up two days before starting my new job.',emoji:'🗝️'},{title:'My one good mug',note:'The only mug I owned for the first month.',emoji:'☕'},{title:'Sunday mornings',note:'The market outside my window. A sound I came to love.',emoji:'🌿'}]};
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}
async function init(){try{db=await new Promise((resolve,reject)=>{const r=indexedDB.open('museum-of-you',1);r.onupgradeneeded=()=>r.result.createObjectStore('exhibitions',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});exhibitions=await new Promise((resolve,reject)=>{const r=db.transaction('exhibitions').objectStore('exhibitions').getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});home()}catch(e){main.innerHTML='<h1>Your museum needs browser storage.</h1><p>Please enable site storage and reload to save your exhibitions.</p>';document.querySelectorAll('[data-new]').forEach(b=>b.disabled=true)}}
const artwork=(i)=>{
const drawings=[`<rect width="240" height="290" fill="#d5cbb7"/><ellipse cx="125" cy="233" rx="56" ry="9" fill="#b6ac96"/><g transform="rotate(-28 120 140)" fill="none" stroke="#a58447" stroke-width="9"><circle cx="120" cy="93" r="29"/><path d="M120 122v100m0-20h24m-24-19h18"/></g>`,`<rect width="240" height="290" fill="#a9b4a4"/><ellipse cx="124" cy="231" rx="70" ry="12" fill="#7d907e"/><path d="M66 121h100v76q-5 40-50 40t-50-40z" fill="#eee5ce"/><path d="M166 137c65-14 57 70 0 58" fill="none" stroke="#eee5ce" stroke-width="14"/><ellipse cx="116" cy="121" rx="50" ry="12" fill="#cbb99b"/><path d="M99 90q-17-20 0-38m27 40q-17-20 0-38" fill="none" stroke="#e0e4d6" stroke-width="3"/>`,`<rect width="240" height="290" fill="#d7c7ad"/><path d="M42 240V55h156v185" fill="#bac8c4" stroke="#f0e9d7" stroke-width="12"/><path d="M120 55v185M42 140h156" stroke="#f0e9d7" stroke-width="8"/><path d="M48 231l28-60 30 60m23 0l25-75 35 75" fill="#6c8065"/><path d="M31 246h178" stroke="#9b8669" stroke-width="10"/>`];return `<svg viewBox="0 0 240 290" role="img" aria-label="${['Illustration of a brass key','Illustration of a ceramic mug','Illustration of an apartment window'][i%3]}">${drawings[i%3]}</svg>`};
function shell(content){return `<div class="museum-space"><div class="ceiling" aria-hidden="true"></div><div class="left-wall" aria-hidden="true"></div><div class="right-wall" aria-hidden="true"></div><div class="museum-floor" aria-hidden="true"></div><div class="wall-trim" aria-hidden="true"></div>${content}</div>`}
function home(){cleanup();document.body.classList.remove('in-exhibition');main.innerHTML=shell(`<div class="lobby-title"><span class="eyebrow">THE PERMANENT COLLECTION OF</span><h1>You.</h1><p>A life in little exhibitions.</p></div><div class="gallery-entrance"><div class="door-light"></div><button class="doorway" data-view="${exhibitions[0]?.id||'sample'}"><span class="door-inner"><span>GALLERY 01</span><strong>${esc(exhibitions[0]?.title||'My first apartment')}</strong><small>Enter exhibition &nbsp; →</small></span></button><div class="door-plaque">${exhibitions.length?'YOUR LATEST CHAPTER':'A SAMPLE EXHIBITION'}<br><b>${exhibitions.length?'Made by you':'My first apartment'}</b></div></div><div class="lobby-manifesto"><span class="eyebrow">EVERY LIFE IS A COLLECTION.</span><p>The keys to your first place.<br>A voice you never want to forget.<br>Things that mean everything.</p><button data-new>Curate a new exhibition &nbsp; ↗</button></div><div class="museum-bench" aria-hidden="true"><i></i></div>`)+`<div class="museum-bottom"><div class="location"><span class="live-dot"></span> THE ENTRANCE HALL <small>Take your time. This place is yours.</small></div><div class="room-list"><span class="eyebrow">EXHIBITIONS</span>${exhibitions.map((e,i)=>`<button data-view="${esc(e.id)}"><small>${String(i+1).padStart(2,'0')}</small>${esc(e.title)} <span>↗</span></button>`).join('')}<button data-view="sample"><small>◌</small>My first apartment <span class="sample-tag">SAMPLE</span></button></div><p class="storage-note">Saved on this browser · No cloud backup</p></div>`;bind()}
function bind(){main.querySelectorAll('[data-new]').forEach(b=>b.onclick=()=>edit());main.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>view(b.dataset.view))}
let roomIndex=0, activeExhibition=null;
function objectArt(o,i){return o.emoji?artwork(i):o.type==='image'?`<img src="${url(o)}" alt="${esc(o.title||'Exhibition object '+(i+1))}">`:'<div class="sound-art" aria-label="Audio object"><span>ııııııııııııııııııııııııı</span><small>A VOICE, PRESERVED.</small></div>'}
function view(id,index=0){cleanup();const e=id==='sample'?sample:exhibitions.find(x=>x.id===id);if(!e)return home();activeExhibition=e;roomIndex=Math.max(0,Math.min(index,e.objects.length-1));document.body.classList.add('in-exhibition');const o=e.objects[roomIndex];main.innerHTML=shell(`<div class="room-wall-title"><span class="eyebrow">${id==='sample'?'SAMPLE COLLECTION':'THE PERSONAL COLLECTION'}</span><h1>${esc(e.title)}</h1><p>${esc(e.intro)}</p></div><div class="exhibit-stage">${o?`<button class="framed-work" id="inspect" aria-label="Look closer at ${esc(o.title||'this object')}"><span class="frame-mat">${objectArt(o,roomIndex)}</span></button><button class="wall-label" id="read-label"><small>${String(roomIndex+1).padStart(2,'0')} / ${String(e.objects.length).padStart(2,'0')}</small><strong>${esc(o.title||'Untitled object')}</strong><span>${o.type==='audio'?'Audio recording':o.emoji?'An object from everyday life':'Personal archive'}</span><em>Look closer &nbsp; +</em></button>`:'<div class="empty-wall"><span>YOUR NEXT CHAPTER</span><h2>A space for something meaningful.</h2><button id="add-first">Place your first object &nbsp; +</button></div>'}</div><div class="museum-bench small-bench" aria-hidden="true"><i></i></div>`)+`<div class="gallery-toolbar"><button class="exit-gallery" id="back">← Entrance hall</button><div class="walk-controls"><button id="previous" aria-label="Previous object" ${roomIndex<=0?'disabled':''}>←</button><span>OBJECT ${o?String(roomIndex+1).padStart(2,'0'):'00'} <i>/ ${String(e.objects.length).padStart(2,'0')}</i></span><button id="next" aria-label="Next object" ${roomIndex>=e.objects.length-1?'disabled':''}>→</button></div>${id==='sample'?'<button data-new>Make your own ↗</button>':'<button id="edit">Curate exhibition ↗</button>'}</div><div class="visitor-hint">${o?'Select the artwork or its label to look closer.':'Add objects to bring this room to life.'}</div>`;$('#back').onclick=home;bind();$('#previous').onclick=()=>view(id,roomIndex-1);$('#next').onclick=()=>view(id,roomIndex+1);if(o){$('#inspect').onclick=()=>inspect(e,o,roomIndex);$('#read-label').onclick=()=>inspect(e,o,roomIndex)}if($('#edit'))$('#edit').onclick=()=>edit(e);if($('#add-first'))$('#add-first').onclick=()=>edit(e);window.scrollTo(0,0)}
function inspect(e,o,i){let d=document.createElement('dialog');d.className='object-detail';d.setAttribute('aria-label',o.title||'Object detail');d.innerHTML=`<button class="detail-close" aria-label="Close object details">×</button><div class="detail-art">${objectArt(o,i)}</div><div class="detail-copy"><span class="eyebrow">OBJECT ${String(i+1).padStart(2,'0')} · ${e.id==='sample'?'FICTIONAL SAMPLE':'PERSONAL ARCHIVE'}</span><h2>${esc(o.title||'Untitled object')}</h2>${o.type==='audio'?`<audio controls src="${url(o)}"></audio>`:''}<p>${esc(o.note||'Some things speak for themselves.')}</p><small>From “${esc(e.title)}”</small></div>`;document.body.append(d);d.querySelector('button').onclick=()=>d.close();d.addEventListener('close',()=>d.remove());d.showModal()}
document.addEventListener('keydown',ev=>{if(!activeExhibition||!document.body.classList.contains('in-exhibition')||document.querySelector('dialog[open]')||['INPUT','TEXTAREA'].includes(ev.target.tagName))return;if(ev.key==='ArrowRight')view(activeExhibition.id,roomIndex+1);if(ev.key==='ArrowLeft')view(activeExhibition.id,roomIndex-1)});
function edit(e){draft=e?structuredClone(e):{id:crypto.randomUUID(),title:'',intro:'',objects:[]};$('#title').value=draft.title;$('#intro').value=draft.intro;$('#error').textContent='';renderObjects();document.querySelector('.delete-exhibition')?.remove();if(e){const del=document.createElement('button');del.type='button';del.className='delete-exhibition';del.textContent='Delete exhibition';del.onclick=async()=>{if(!confirm('Delete this exhibition and its objects? This cannot be undone.'))return;try{await write('delete',e.id);exhibitions=exhibitions.filter(x=>x.id!==e.id);dialog.close();home();toast('Exhibition deleted')}catch{$('#error').textContent='Could not delete. Please try again.'}};$('#form').append(del)}dialog.showModal();$('#title').focus()}
function renderObjects(){const list=$('#objects');list.replaceChildren();$('#count').textContent=`${draft.objects.length} / 3 to get started`;draft.objects.forEach((o,i)=>{const el=document.createElement('div');el.className='object-edit';el.innerHTML=`${o.type==='image'?`<img src="${url(o)}" alt="Object preview">`:'<span class="cover-audio">♫</span>'}<div><input aria-label="Object ${i+1} title" maxlength="100" placeholder="Object title (optional)" value="${esc(o.title)}"><textarea aria-label="Object ${i+1} note" maxlength="2000" rows="2" placeholder="What would you like to remember about this?">${esc(o.note)}</textarea><div class="object-actions"><button type="button" data-up ${i===0?'disabled':''}>↑ Move earlier</button><button type="button" data-down ${i===draft.objects.length-1?'disabled':''}>↓ Move later</button><button type="button" data-remove>Remove</button></div></div>${o.type==='audio'?`<audio controls src="${url(o)}"></audio>`:''}`;el.querySelector('input').oninput=ev=>o.title=ev.target.value;el.querySelector('textarea').oninput=ev=>o.note=ev.target.value;el.querySelector('[data-remove]').onclick=()=>{draft.objects.splice(i,1);renderObjects()};el.querySelector('[data-up]').onclick=()=>{[draft.objects[i-1],draft.objects[i]]=[draft.objects[i],draft.objects[i-1]];renderObjects()};el.querySelector('[data-down]').onclick=()=>{[draft.objects[i+1],draft.objects[i]]=[draft.objects[i],draft.objects[i+1]];renderObjects()};list.append(el)})}
$('#upload').onchange=ev=>{const errors=[];for(const f of ev.target.files){if(!/^(image|audio)\//.test(f.type)){errors.push(`${f.name}: choose an image or audio file.`);continue}if(f.size>20*1024*1024){errors.push(`${f.name}: exceeds 20 MB.`);continue}draft.objects.push({id:crypto.randomUUID(),type:f.type.startsWith('image/')?'image':'audio',blob:f,title:'',note:''})}$('#error').textContent=errors.join(' ');ev.target.value='';renderObjects()};
function write(method,value){return new Promise((resolve,reject)=>{const tx=db.transaction('exhibitions','readwrite');tx.objectStore('exhibitions')[method](value);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
$('#form').onsubmit=async ev=>{ev.preventDefault();const b=ev.submitter;b.disabled=true;draft.title=$('#title').value.trim()||'Untitled exhibition';draft.intro=$('#intro').value.trim();draft.updated=Date.now();try{await write('put',draft);const idx=exhibitions.findIndex(e=>e.id===draft.id);if(idx>=0)exhibitions[idx]=draft;else exhibitions.unshift(draft);dialog.close();view(draft.id);toast('Exhibition saved on this browser')}catch{$('#error').textContent='Could not save. Browser storage may be full. Your edits are still here; try removing a large file.'}finally{b.disabled=false}};
function closeEditor(){if(confirm('Close without saving these edits?')){dialog.close();home()}}
$('#close').onclick=closeEditor;dialog.addEventListener('cancel',e=>{e.preventDefault();closeEditor()});document.querySelector('header [data-new]').onclick=()=>edit();document.querySelectorAll('header a').forEach(a=>a.onclick=e=>{e.preventDefault();home()});init();
